index 50ed8f0..4c412db 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -416,6 +416,19 @@ extern "C" int c_bufcache_status(natl *blocks, natl *io_count)
 //   ESAME 2023-01-11 )

 // ( SOLUZIONE 2023-01-11
+/// Trova un buffer nella cache contenente il blocco specificato.
+/// @param d		descrittore dell'hard disk
+/// @param block	id del blocco da cercare
+/// @return		puntatore al buffer trovato, nullptr se non trovato
+buf_des* bufcache_find(des_ata* d, natl block)
+{
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		buf_des *b = &d->bufcache[i];
+		if (b->full && b->block == block)
+			return b;
+	}
+	return nullptr;
+}
 //   SOLUZIONE 2023-01-11 )
 /// Piedino dell'APIC per le richieste di interruzione dell'hard disk
 const natb HD_IRQ = 14;
@@ -495,6 +508,34 @@ extern "C" void c_readhd_n(natb vetti[], natl primo, natb quanti)

 /// @todo Gestire l'operazione tenendo conto della buffer cache.
 // ( SOLUZIONE 2023-01-11
+	sem_wait(d->mutex);
+	for (natb i = 0; i < quanti; i++) {
+		natl block = primo + i;
+		buf_des *b = bufcache_find(d, block);
+		if (b) {
+			bufcache_promote(b);
+			for (natq j = 0; j < DIM_BLOCK; j++)
+				vetti[i * DIM_BLOCK + j] = b->buf[j];
+		} else {
+			int slot = -1;
+			for (int k = 0; k < MAX_BUF_DES; k++) {
+				if (!d->bufcache[k].full) { slot = k; break; }
+			}
+			if (slot < 0)
+				slot = d->lru;
+			buf_des *target = &d->bufcache[slot];
+			if (target->full)
+				bufcache_promote(target);
+			target->full = true;
+			target->block = block;
+			starthd_in(d, target->buf, block, 1);
+			sem_wait(d->sincr);
+			bufcache_promote(target);
+			for (natq j = 0; j < DIM_BLOCK; j++)
+				vetti[i * DIM_BLOCK + j] = target->buf[j];
+		}
+	}
+	sem_signal(d->mutex);
 //   SOLUZIONE 2023-01-11 )
 //   ESAME 2023-01-11 ]
 }
@@ -543,6 +584,26 @@ extern "C" void c_writehd_n(natb vetto[], natl primo, natb quanti)
 	//sem_signal(d->mutex);
 /// @todo Gestire l'operazione tenendo conto della buffer cache.
 // ( SOLUZIONE 2023-01-11
+	sem_wait(d->mutex);
+	for (natb i = 0; i < quanti; i++) {
+		natl block = primo + i;
+		buf_des *b = bufcache_find(d, block);
+		if (b) {
+			// Write-through: aggiorna la cache e scrivi su disco
+			for (natq j = 0; j < DIM_BLOCK; j++)
+				b->buf[j] = vetto[i * DIM_BLOCK + j];
+			bufcache_promote(b);
+			starthd_out(d, vetto + i * DIM_BLOCK, block, 1);
+			sem_wait(d->sincr);
+		}
+		// No-allocate: se il blocco non è in cache, scrivi solo su disk
+		// senza portarlo in cache
+		else {
+			starthd_out(d, vetto + i * DIM_BLOCK, block, 1);
+			sem_wait(d->sincr);
+		}
+	}
+	sem_signal(d->mutex);
 //   SOLUZIONE 2023-01-11 )
 //   ESAME 2023-01-11 ]
 }
@@ -735,6 +796,14 @@ bool hd_init()
 	hd::enable_intr();

 // ( SOLUZIONE 2023-01-11
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		d->bufcache[i].full = false;
+		d->bufcache[i].next = -1;
+		d->bufcache[i].prev = -1;
+	}
+	d->lru = -1;
+	d->mru = -1;
+	d->io_count = 0;
 //   SOLUZIONE 2023-01-11 )

 	return true;
